  },
  "designs": [
    {
      "screenId": "wqucLs7TJesh/screens/new_screen4.jsx",
      "screenName": "Premium Paywall (Light)",
      "source": "import Icon from '@global/Icon';
import PaywallFeatureItem from '@components/PaywallFeatureItem';

export const displayName = 'Premium Paywall (Light)';
export const screenSize = 'mobile';

export default function PremiumPaywallLightScreen() {
  const features = [
    t('Unlimited Mock Tests'),
    t('AI Notes Generator'),
    t('PYQ Analysis'),
    t('No Ads')
  ];

  return (
    <div className="flex flex-col min-h-screen mobile-screen relative bg-white overflow-x-hidden overflow-y-auto text-foreground isolate font-body">

      {/* Top Header */}
      <header className="flex items-center justify-between px-5 py-4 z-20 sticky top-0 bg-white/90 backdrop-blur-md">
        <button className="w-10 h-10 rounded-full bg-muted/80 flex items-center justify-center border border-border/50 text-foreground shadow-sm hover:bg-muted transition-colors">
          <Icon i="x" size={20} />
        </button>
        <div className="bg-error/10 border border-error/20 text-error font-bold px-3 py-1.5 rounded-full text-xs tracking-wide flex items-center gap-1.5 shadow-sm">
          <Icon i="clock" size={14} className="animate-pulse" />
          {t('Offer ends in 02:15:30')}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6 pt-3 pb-8 z-10 flex flex-col items-center">

        {/* Title Section */}
        <div className="text-center mb-8 w-full">
          <h1 className="text-3xl font-headings font-extrabold mb-2 text-foreground tracking-tight">
            {t('Upgrade to Premium')}
          </h1>
          <p className="text-muted-foreground text-[15px] font-medium">
            {t('Unlock all AI-powered features')}
          </p>
        </div>

        {/* Main Offer Card */}
        <div className="w-full relative mb-8">
          {/* Subtle soft shadow glow behind card */}
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-100 to-orange-100 rounded-[24px] blur-xl opacity-70"></div>

          <div className="relative bg-gradient-to-br from-indigo-50 via-purple-50 to-orange-50 border border-purple-100 rounded-[24px] p-6 text-center shadow-lg">

            {/* Top Badge */}
            <div className="absolute -top-3.5 left-0 right-0 flex justify-center items-center">
              <span className="bg-primary text-primary-foreground text-[10px] font-bold px-4 py-1.5 rounded-full uppercase tracking-wider shadow-md">
                {t('Most Popular')}
              </span>
            </div>

            <div className="text-orange-600 font-bold text-sm tracking-wide uppercase mb-4 mt-2 flex items-center justify-center gap-1.5">
              <Icon i="flame" size={16} /> {t('Special Offer')}
            </div>

            <div className="flex items-baseline justify-center gap-1.5 mb-3">
              <span className="text-5xl font-headings font-extrabold text-foreground tracking-tight">{t('₹99')}</span>
              <span className="text-muted-foreground text-lg font-medium">{t('/month')}</span>
            </div>

            <div className="inline-block bg-white text-success border border-success/20 text-xs font-bold px-3 py-1.5 rounded-lg shadow-sm">
              {t('50% OFF (was ₹199)')}
            </div>

          </div>
        </div>

        {/* Free Trial Banner */}
        <div className="w-full bg-white border border-border rounded-[20px] p-5 mb-8 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
          <div>
            <div className="font-bold text-foreground text-[15px] mb-1">{t('7 Days Free Trial 🎁')}</div>
            <div className="text-xs text-muted-foreground font-medium">{t('Then ₹99/month. Cancel Anytime.')}</div>
          </div>
          <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center border border-primary/20 flex-shrink-0">
            <Icon i="unlock" size={24} className="text-primary" />
          </div>
        </div>

        {/* Features Checklist */}
        <div className="w-full space-y-4 pl-3 mb-6 flex-1">
          {features.map((feature, idx) => (
            <PaywallFeatureItem key={idx} text={feature} />
          ))}
        </div>

      </main>

      {/* Bottom Sticky CTA Area */}
      <footer className="px-5 pt-4 pb-safe bg-white border-t border-border/50 z-20 sticky bottom-0 shadow-[0_-10px_30px_rgba(0,0,0,0.03)]">

        <button className="w-full bg-primary text-primary-foreground rounded-[20px] py-4 px-6 shadow-lg shadow-primary/25 flex items-center justify-center gap-2 mb-4 relative overflow-hidden group">
          {/* Subtle static "shimmer" effect representing the glow/animation */}
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent skew-x-12 translate-x-[-100%] pointer-events-none"></div>
          <span className="font-extrabold text-[17px]">{t('Start 7-Day Free Trial')}</span>
          <Icon i="arrow-right" size={20} />
        </button>

        {/* Payment Methods & Trust Badges */}
        <div className="flex flex-col items-center justify-center pb-2">

          <div className="flex items-center gap-1.5 text-[10px] text-success font-bold tracking-wider uppercase mb-3">
            <Icon i="shield-check" size={14} />
            {t('Secure Payment 🔒')}
          </div>

          <div className="flex items-center gap-3 mb-3 text-muted-foreground">
            <Icon i="credit-card" size={20} />
            <div className="flex gap-2 items-center">
              <span className="text-[10px] font-bold border border-border bg-input rounded px-2 py-0.5 text-foreground">{t('UPI')}</span>
              <span className="text-[10px] font-bold border border-border bg-input rounded px-2 py-0.5 text-foreground">{t('Cards')}</span>
              <span className="text-[10px] font-bold border border-border bg-input rounded px-2 py-0.5 text-foreground">{t('Wallet')}</span>
            </div>
            <Icon i="smartphone" size={20} />
          </div>

        </div>

      </footer>

    </div>
  );
}",
      "genType": "components"
    }
  ],
  "sharedFiles": [
    {
      "path": "/style.css",
      "content": "@theme {
