  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 36px;
}"
    },
    {
      "path": "/components/PaywallFeatureItem.jsx",
      "content": "import Icon from '@global/Icon';

export default function PaywallFeatureItem({ text }) {
  return (
    <div className="flex items-center gap-3">
      <div className="w-6 h-6 rounded-full bg-primary/10 flex items-center justify-center border border-primary/20 flex-shrink-0">
        <Icon i="check" size={14} className="text-primary font-bold" />
      </div>
      <span className="font-semibold text-[15px] text-foreground">{text}</span>
    </div>
  );
}"
    }
  ]
}
